// === Tab: mySketch ===
let fbo;
let font;

let particlePositions = [];
let particleGlyphs = [];

let audio;
let audioStarted = false;

let words = [
  "neuralink",
  "mente",
  "aplicación",
  "click",
  "textura",
  "multitasking",
  "cerebro",
  "serie",
  "automáticas",
  "proceso",
  "pensamiento",
  "sistema",
  "interfaz",
  "2.3",
  "mecánica",
  "usuarios",
  "dispositivo",
  "consumo",
  "metros",
  "2027",
  "minería",
  "litio",
  "cobre",
  "energética",
  "cambia",
  "arden",
  "ácida",
  "ciudad",
  "ambiental",
  "sueño",
	"agua",
  "lujo",
];

let currentWord = 0;
let animationStartTime = 0;

const transitionDuration = 1994;
const holdDuration = 1994;

// ───────────── VARIACIÓN ─────────────
let buildModes = ["noise", "top", "sides", "center", "scan"];
let glyphSets = [
  ["0","1"],
  ["$","#"],
  ["░","▒"],
  ["#","%"],
  ["_","|"]
];

let currentMode = "noise";
let currentGlyphSet = ["0","1"];
let glitchWord = false;

// ───────────── AUDIO ─────────────
function initAudio() { 
	if (audioStarted) return; 
	audio = new Audio( "https://deckard.openprocessing.org/user308806/visual2842832/he9d03f6e58607c0815cfd7d0a2031ddc/audio.mp3" ); 
	audio.loop = true; 
	audio.volume = 1; 
	audio.play(); 
	audioStarted = true;
}

function mousePressed() {
  initAudio();
}

// ───────────── SETUP ─────────────
async function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);

  font = await loadFont(
    "https://fonts.gstatic.com/s/ubuntu/v21/4iCv6KVjbNBYlgoCxCvTt2aMH4V_gg.ttf"
  );

  fbo = createFramebuffer({ width: 600, height: 150, density: 1 });

  animationStartTime = millis();
  setNewWord(0);
}

// ───────────── WORD LOGIC ─────────────
function setNewWord(index) {
  currentWord = index;
  currentMode = random(buildModes);
  currentGlyphSet = random(glyphSets);
  glitchWord = random() < 0.25;

  drawWordToFBO(words[currentWord]);
  buildParticles();
}

// ───────────── PARTICLES ─────────────
function drawWordToFBO(word) {
  if (!word) return;

  let size = constrain(70 - word.length * 3, 14, 60);

  fbo.draw(() => {
    background(0);
    fill(255);
    textFont(font);
    textAlign(CENTER, CENTER);
    textSize(size);
    text(word, 0, 0);
  });

  fbo.loadPixels();
}

function buildParticles() {
  particlePositions = [];
  particleGlyphs = [];

  for (let x = 0; x < fbo.width; x += 2) {
    for (let y = 0; y < fbo.height; y += 2) {
      let idx = (y * fbo.width + x) * 4;
      if (fbo.pixels[idx] > 0) {
        particlePositions.push({
          x, y,
          seed: (x + y * fbo.width) * 0.01
        });
        particleGlyphs.push(random(currentGlyphSet));
      }
    }
  }

  for (let i = 0; i < 3000; i++) {
    particlePositions.push({
      x: random(-fbo.width, fbo.width * 2),
      y: random(-fbo.height, fbo.height * 2),
      seed: random() * 1000
    });
    particleGlyphs.push(random(currentGlyphSet));
  }
}

// ───────────── DRAW ─────────────
function draw() {
  background(0);

  let elapsed = millis() - animationStartTime;
  let cycle = transitionDuration + holdDuration;

  let wordIndex = floor(elapsed / cycle) % words.length;
  if (wordIndex !== currentWord) {
    setNewWord(wordIndex);
  }

  let t = elapsed % cycle;
  let progress = constrain(map(t, 0, transitionDuration, 0, 1), 0, 1);
  progress = progress * progress * (3 - 2 * progress);

  push();
  scale(min(width / 180, height / 115));
  translate(-fbo.width / 2, -fbo.height / 2);

  textFont(font);
  textSize(2.5);
  textAlign(CENTER, CENTER);

  for (let i = 0; i < particlePositions.length; i++) {
    let p = particlePositions[i];
    let g = particleGlyphs[i];

    let baseX = p.x;
    let baseY = p.y;

    if (currentMode === "top")
      baseY = lerp(-200, p.y, progress);

    if (currentMode === "center") {
      baseX = lerp(fbo.width / 2, p.x, progress);
      baseY = lerp(fbo.height / 2, p.y, progress);
    }

    if (currentMode === "sides")
      baseX = lerp(p.x < fbo.width / 2 ? -200 : fbo.width + 200, p.x, progress);

    if (currentMode === "scan")
      baseY = lerp(p.y + sin(elapsed * 0.01) * 80, p.y, progress);

    let offsetX =
      lerp(120 * (noise(p.seed) - 0.5), 0, progress);
    let offsetY =
      lerp(60 * (noise(p.seed + 50) - 0.5), 0, progress);

    if (glitchWord && random() < 0.015) continue;

    if (glitchWord) {
      offsetX += random(-2, 2);
      offsetY += random(-2, 2);
    }

    fill(255, lerp(100, 255, progress));
    text(g, baseX + offsetX, baseY + offsetY);
  }

  pop();
}

// ───────────── RESIZE ─────────────
function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

